        instructions = args[0]
    else:
        instructions = args
    for instruction in instructions:
        if instruction[0] == 'push':
            stack.append(instruction[1])
        elif instruction[0] == 'add':
            b = stack.pop()
            a = stack.pop()
            stack.append(a + b)
        elif instruction[0] == 'multiply':
            b = stack.pop()
            a = stack.pop()
            stack.append(a * b)
        elif instruction[0] == 'negate':
            a = stack.pop()
            stack.append(-a)
        else:
            raise ValueError(f"Unknown instruction: {instruction[0]}")
    if stack:
        return stack[-1]
    else:
        return None"}

